package io.rift.cronos;
import org.json.*;import java.util.*;import java.math.BigInteger;import java.io.*;
/** Contract-scoped, explicit pages of transfer-log hints. No wallet-wide completeness claim. */
public final class TransferDiscovery {
 public interface Rpc {Object call(String method,JSONArray params)throws Exception;void requireCronos()throws Exception;}
 private TransferDiscovery(){}
 private static String quantity(long n){return "0x"+Long.toHexString(n);}
 private static long number(Object value){if(!(value instanceof String)||!((String)value).matches("0x(?:0|[1-9a-fA-F][a-fA-F0-9]{0,13})"))throw new IllegalArgumentException("Invalid block/log quantity");BigInteger n=new BigInteger(((String)value).substring(2),16);return DiscoveryPolicy.block(n.toString());}
 public static String anchor(Rpc rpc,long block)throws Exception{Object value=rpc.call("eth_getBlockByNumber",new JSONArray().put(quantity(block)).put(false));if(!(value instanceof JSONObject))throw new IOException("Block anchor unavailable");JSONObject b=(JSONObject)value;if(number(b.get("number"))!=block)throw new IOException("Block anchor number mismatch");return ReadPolicy.hash(b.getString("hash"));}
 public static JSONObject scan(Rpc rpc,String owner,String contract,String standard,String start,String count)throws Exception{
  owner=ReadPolicy.address(owner);contract=ReadPolicy.address(contract);standard=ReadPolicy.standard(standard);int span=DiscoveryPolicy.span(count);if(!start.equals("recent"))DiscoveryPolicy.block(start);rpc.requireCronos();long head=number(rpc.call("eth_blockNumber",new JSONArray()));long from=start.equals("recent")?Math.max(0,head-span+1):DiscoveryPolicy.block(start);if(from>head)throw new IOException("Starting block is beyond current provider head");long to=Math.min(head,from+span-1);String before=anchor(rpc,to),ownerTopic=DiscoveryPolicy.ownerTopic(owner);Map<String,String> events=new HashMap<>();Map<String,JSONObject> candidates=new LinkedHashMap<>();int total=0,ignored=0;
  for(boolean incoming:new boolean[]{true,false}){JSONArray topics=new JSONArray();if(standard.equals("ERC-721")){topics.put(DiscoveryPolicy.TRANSFER);if(incoming)topics.put(JSONObject.NULL);topics.put(ownerTopic);}else{topics.put(new JSONArray().put(DiscoveryPolicy.SINGLE).put(DiscoveryPolicy.BATCH)).put(JSONObject.NULL);if(incoming)topics.put(JSONObject.NULL);topics.put(ownerTopic);}
   JSONObject filter=new JSONObject().put("address",contract).put("fromBlock",quantity(from)).put("toBlock",quantity(to)).put("topics",topics);Object value=rpc.call("eth_getLogs",new JSONArray().put(filter));if(!(value instanceof JSONArray))throw new IOException("Invalid log page");JSONArray logs=(JSONArray)value;if(logs.length()>DiscoveryPolicy.MAX_LOGS||total+logs.length()>DiscoveryPolicy.MAX_LOGS)throw new IOException("Log page exceeds 512 events; choose a smaller block span");total+=logs.length();
   for(int i=0;i<logs.length();i++){JSONObject log=logs.getJSONObject(i);if(!contract.equals(ReadPolicy.address(log.getString("address")))||!(log.get("removed") instanceof Boolean)||log.getBoolean("removed"))throw new IOException("Removed/out-of-scope log; retry a smaller recent page");long height=number(log.get("blockNumber"));if(height<from||height>to)throw new IOException("Log block outside requested page");String blockHash=ReadPolicy.hash(log.getString("blockHash"));if(height==to&&!before.equals(blockHash))throw new IOException("Log anchor mismatch");String tx=ReadPolicy.hash(log.getString("transactionHash")),index=Long.toString(number(log.get("logIndex")));JSONArray raw=log.getJSONArray("topics");if(raw.length()>4)throw new IOException("Unexpected event topics");List<String> ts=new ArrayList<>();for(int j=0;j<raw.length();j++)ts.add(raw.getString(j));String data=log.getString("data");List<String> ids=DiscoveryPolicy.tokens(standard,owner,incoming,ts,data);String key=blockHash+":"+tx+":"+index,encoded=ts.toString().toLowerCase(Locale.ROOT)+":"+data.toLowerCase(Locale.ROOT)+":"+height;String previous=events.putIfAbsent(key,encoded);if(previous!=null){if(!previous.equals(encoded))throw new IOException("Conflicting duplicate log");continue;}if(ids.isEmpty())ignored++;for(String id:ids){candidates.putIfAbsent(id,new JSONObject().put("contract",contract).put("standard",standard).put("tokenId",id).put("label","Transfer-log hint"));if(candidates.size()>DiscoveryPolicy.MAX_CANDIDATES)throw new IOException("Page exceeds 200 candidate IDs; choose a smaller span");}
   }
  }
  if(!before.equals(anchor(rpc,to)))throw new IOException("Page-end block changed during scan; no page accepted");JSONArray rows=new JSONArray();for(JSONObject row:candidates.values())rows.put(row);return new JSONObject().put("owner",owner).put("contract",contract).put("standard",standard).put("fromBlock",Long.toString(from)).put("toBlock",Long.toString(to)).put("headBlock",Long.toString(head)).put("endBlockHash",before).put("nextFromBlock",to<head?Long.toString(to+1):JSONObject.NULL).put("suggestedRecheckFromBlock",Long.toString(Math.max(0,to-11))).put("logResponses",total).put("uniqueEvents",events.size()).put("ignoredFungibleOrZeroEvents",ignored).put("candidates",rows).put("coverage","Only provider-reported transfers for this contract/owner/range. Provider completeness and canonical history are not proven. Page-end anchor rechecked, not finality. Revisit overlap after reorgs.").put("warning","Touched-token hints only, including assets sent away. Not current holdings, contract standard/authenticity, approvals or wallet-wide discovery. No signing, automatic continuation or candidate save.");
 }
}
